    const originalPosition = tile.position.clone();
    const originalScale = tile.scale.clone();

    // Collect meshes, clone materials, apply PBR
    const meshes = [];
    const clonedMaterials = [];

    tile.traverse((child) => {
        if (child.isMesh) {
            meshes.push(child);

            // Clone material to avoid affecting cached GLB
            if (child.material) {
                const mat = child.material.clone();
                child.material = mat;
                clonedMaterials.push(mat);

                // Machined-metal PBR per design tokens
                mat.metalness = Math.min(mat.metalness ?? 0.5, 0.55);
                mat.roughness = Math.max(mat.roughness ?? 0.6, 0.5);
                if ('clearcoat' in mat) {
                    mat.clearcoat = Math.min(mat.clearcoat ?? 0, 0.25);
                }

                // Set up emissive for accent edge
                mat.emissive = new THREE.Color('#ff2a38');
                mat.emissiveIntensity = 0;

                mat.needsUpdate = true;
            }
        }
    });

    // State
    const state = {
        hovered: false,
        pressed: false,
        focused: false
    };

    // Hover: rise-in (subtle, 0.15 scene units)
    const handleHover = (isHovering) => {
        state.hovered = isHovering;
        gsap.to(tile.position, {
            y: originalPosition.y + (isHovering ? 0.15 : 0),
            duration: 0.7,
            ease: 'power3.out'
        });
    };

    // Click: press-down + emit
    const handleClick = () => {
        if (state.pressed) return;
        state.pressed = true;

        gsap.timeline({ onComplete: () => { state.pressed = false; } })
            .to(tile.scale, {
                x: originalScale.x * 0.97,
                y: originalScale.y * 0.97,
                z: originalScale.z * 0.97,
                duration: 0.12,
                ease: 'back.out(1.7)'
            })
            .to(tile.scale, {
                x: originalScale.x,
                y: originalScale.y,
                z: originalScale.z,
                duration: 0.25,
                ease: 'power4.out'
            });

        if (ctx.emit) {
            ctx.emit('hub-home.select', {
                source: config.id || 'stat-tile',
                dataBindings: config.dataBindings || []
            });
        }
    };

    // Focus: accent edge (signal red emissive)
    const handleFocus = (isFocused) => {
        state.focused = isFocused;
        clonedMaterials.forEach((mat) => {
            gsap.to(mat, {
                emissiveIntensity: isFocused ? 0.5 : 0,
                duration: 0.4,
                ease: 'power2.out'
            });
        });
    };

    // Apply cinematic primitives
    const primitiveCleanups = [];
    if (config.cinematicPrimitives) {
        config.cinematicPrimitives.forEach((primitive) => {
            if (ctx.primitives && ctx.primitives[primitive.name]) {
                const result = ctx.primitives[primitive.name](tile, primitive.params || {});
                if (result && typeof result === 'function') {
                    primitiveCleanups.push(result);
                }
            }
        });
    }

    // Store on userData
    tile.userData.handlers = {
        hover: handleHover,
        click: handleClick,
        focus: handleFocus
    };

    tile.userData.dataBindings = config.dataBindings || [];
    tile.userData.atlasRegion = { atlas: 0, rect: [0, 0, 512, 320] };
    tile.userData.nodeType = 'stat-tile';
    tile.userData.parent = 'hub-home';
    tile.userData.siblings = ['home-headline', 'home-subhead', 'home-hero'];

    // Data update callback for when trpc.pricing.tiers data arrives
    tile.userData.updateData = (data) => {
        if (data && data.tiers) {
            tile.userData.tiers = data.tiers;
        }
    };

    // Cleanup
    tile.userData.cleanup = () => {
        gsap.killTweensOf(tile.position);
        gsap.killTweensOf(tile.scale);
        gsap.killTweensOf(tile.rotation);

        clonedMaterials.forEach((mat) => {
            gsap.killTweensOf(mat);
            mat.dispose();
        });

        primitiveCleanups.forEach((cleanup) => {
            if (typeof cleanup === 'function') cleanup();
        });
    };

    return tile;
}
